/** Project a longitude/latitude into a view's SVG coordinates. */
export function project(v: MapView, lon: number, lat: number): [number, number] {
  return [v.x + (lon - v.lon0) * v.cosLat * v.k, v.y + (v.lat1 - lat) * v.k]
}
